#include "stdlib/stats/base/ndarray/smskmin.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include "stdlib/ndarray/ctor.h"
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <math.h>
#include <sys/time.h>

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %g\n", elapsed );
	printf( "  rate: %g\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec / 1.0e6;
}

/**
* Generates a random number on the interval [0,1).
*
* @return random number
*/
static float rand_double( void ) {
	int r = rand();
	return (float)r / ( (float)RAND_MAX + 1.0f );
}

/**
* Runs a benchmark.
*
* @return elapsed time in seconds
*/
static double benchmark( void ) {
	double elapsed;
	double t;
	float x[ 100 ];
	uint8_t mask[ 100 ];
	int i;

	for ( i = 0; i < 100; i++ ) {
		x[ i ] = ( rand_double() * 100.0f ) - 50.0f;
		mask[ i ] = ( rand_double() < 0.2 ) ? 1 : 0;
	}

	int64_t shape[] = { 100 };
	int64_t stridesX[] = { 1 };
	int64_t stridesMask[] = { 1 };
	int64_t offset = 0;

	struct ndarray *arrX = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, x, 1, shape, stridesX, offset, STDLIB_NDARRAY_ROW_MAJOR );
	struct ndarray *arrMask = stdlib_ndarray_allocate( STDLIB_NDARRAY_UINT8, mask, 1, shape, stridesMask, offset, STDLIB_NDARRAY_ROW_MAJOR );

	const struct ndarray *arrays[] = { arrX, arrMask };

	int iterations = 1000000;
	float v;

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		v = stdlib_stats_smskmin( arrays );
		if ( v != v ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( v != v ) {
		printf( "should not return NaN\n" );
	}
	stdlib_ndarray_free( arrX );
	stdlib_ndarray_free( arrMask );

	print_results( iterations, elapsed );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;

	count = 0;
	print_version();
	printf( "# c::%s\n", "smskmin" );
	elapsed = benchmark();
	print_results( 1000000, elapsed );
	printf( "ok %d benchmark finished\n", ++count );
	print_summary( count, count );
	return 0;
}
